mapper.select:
/* common.mpvo.selectMasterMpVoVocBizGenerateStatePop */ SELECT TO_CHAR(A.CD_DATE,'YYYY/MM/DD') AS CD_DATE, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE = A.BUYER AND SYS_TYPE = A.SYS_TYPE AND BUSINESS_COND LIKE '%B%') AS BUYER_NAME, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.CD_USER_ID AND SYS_TYPE='KA') AS CD_USER_NAME, DECODE(A.SYS_TYPE ,'KA', (SELECT DESCRIPTION_LOC||'//'||SPECIFICATION FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) ,'KM', (SELECT MAX(DESCRIPTION_LOC||'//'||SPECIFICATION) FROM ITEMMAST WHERE STDCATLG_ID = A.BUYER_ITEM_NO AND USE_FLAG = 'X' GROUP BY STDCATLG_ID) -- ,'SA', (SELECT DESCRIPTION||'//'||SPECIFICATION FROM MALL.MALLCQDT -- WHERE ITEM_NO = A.BUYER_ITEM_NO) -- ,'WD', (SELECT DESCRIPTION||'//'||SPECIFICATION FROM MALL.WELDCQDT -- WHERE ITEM_NO = A.BUYER_ITEM_NO ) ,'KW', (SELECT PRODUCT_NAME||'//'||INDUSTRIAL_STANDARD FROM STREAM.MST_PRODUCT WHERE PRODUCT_CODE = A.BUYER_ITEM_NO)) AS ITEM_DESC, ROUND(A.DF_DATE-A.CD_DATE,0) AS LEAD_TIME, TO_CHAR(A.DF_DATE,'YYYY/MM/DD') AS DF_DATE, A.REQ_USER_NAME AS REQ_USER_NAME, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.DS_USER_ID AND SYS_TYPE='KA') AS DS_USER_NAME, DECODE(A.IMPUTE_TYPE,'SS','공급사','MM','KeP','MS','KeP/공급사') AS IMPUTE_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = A.CLAIM_TYPE) AS CLAIM_TEXT, DECODE(A.RUB_TYPE,'A','매우만족','B','만족','C','보통','D','불만','F','매우불만','미평가') AS RUB_TYPE, A.VC_NO, A.BUYER_ITEM_NO, A.REQ_REMARK, A.DS_REMARK_A, A.DS_REMARK_B, A.DS_REMARK_C, A.DF_REMARK, A.DS_DEPT, A.CLAIM_TYPE, A.RECV_FLAG, A.CD_USER_ID, A.DS_USER_ID, A.BUYER, A.CLAIM_GRADE, A.REQ_USER_ID, A.IMPUTE_AGENT, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE = A.IMPUTE_AGENT AND SYS_TYPE = A.SYS_TYPE AND BUSINESS_COND LIKE '%S%') AS AGENT_NAME, A.IMPUTE_TYPE AS IMPUTE_TYPE2, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC03' AND CODE = A.CLAIM_MASTER) AS CLAIM_MASTER FROM KEPAVCDT A, (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'VC01' AND TEXT3 = 'C') B WHERE A.DS_DEPT = #{st_ds_dept_code} AND A.CLAIM_TYPE = B.CODE AND A.RECV_FLAG = #{st_recv_type}
AND A.DS_USER_ID = #{st_ds_user_id}
AND TO_CHAR(A.CD_DATE,'YYYYMMDD') BETWEEN #{st_fromDate} AND #{st_toDate} ORDER BY A.BUYER, A.VC_NO

/* common.mpvo.selectMasterMpVoVocAgntcmpyGenerateStatePop */ SELECT TO_CHAR(A.CD_DATE,'YYYY/MM/DD') AS CD_DATE, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE = A.BUYER AND SYS_TYPE = A.SYS_TYPE AND BUSINESS_COND LIKE '%B%') AS BUYER_NAME, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.CD_USER_ID AND SYS_TYPE='KA') AS CD_USER_NAME, DECODE(A.SYS_TYPE ,'KA', (SELECT DESCRIPTION_LOC||'//'||SPECIFICATION FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO) ,'KM', (SELECT MAX(DESCRIPTION_LOC||'//'||SPECIFICATION) FROM ITEMMAST WHERE STDCATLG_ID = A.BUYER_ITEM_NO AND USE_FLAG = 'X' GROUP BY STDCATLG_ID) -- ,'SA', (SELECT DESCRIPTION||'//'||SPECIFICATION FROM MALL.MALLCQDT -- WHERE ITEM_NO = A.BUYER_ITEM_NO) -- ,'WD', (SELECT DESCRIPTION||'//'||SPECIFICATION FROM MALL.WELDCQDT -- WHERE ITEM_NO = A.BUYER_ITEM_NO ) ,'KW', (SELECT PRODUCT_NAME||'//'||INDUSTRIAL_STANDARD FROM STREAM.MST_PRODUCT WHERE PRODUCT_CODE = A.BUYER_ITEM_NO)) AS ITEM_DESC, ROUND(A.DF_DATE-A.CD_DATE,0) AS LEAD_TIME, TO_CHAR(A.DF_DATE,'YYYY/MM/DD') AS DF_DATE, A.REQ_USER_NAME AS REQ_USER_NAME, (SELECT USER_NAME_LOC FROM V_VOC_ICOMLUSR WHERE USER_ID = A.DS_USER_ID AND SYS_TYPE='KA') AS DS_USER_NAME, DECODE(A.IMPUTE_TYPE,'SS','공급사','MM','KeP','MS','KeP/공급사') AS IMPUTE_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = A.CLAIM_TYPE) AS CLAIM_TEXT, DECODE(A.RUB_TYPE,'A','매우만족','B','만족','C','보통','D','불만','F','매우불만','미평가') AS RUB_TYPE, A.VC_NO, A.BUYER_ITEM_NO, A.REQ_REMARK, A.DS_REMARK_A, A.DS_REMARK_B, A.DS_REMARK_C, A.DF_REMARK, A.DS_DEPT, A.CLAIM_TYPE, A.RECV_FLAG, A.CD_USER_ID, A.DS_USER_ID, A.BUYER, A.CLAIM_GRADE, A.REQ_USER_ID, A.IMPUTE_AGENT, (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE = A.IMPUTE_AGENT AND SYS_TYPE = A.SYS_TYPE AND BUSINESS_COND LIKE '%S%') AS AGENT_NAME, A.IMPUTE_TYPE AS IMPUTE_TYPE2, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC03' AND CODE = A.CLAIM_MASTER) AS CLAIM_MASTER FROM KEPAVCDT A, (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'VC01' AND TEXT3 = 'C') B WHERE A.SYS_TYPE = #{st_sys_type} AND A.IMPUTE_AGENT = #{st_agent_code} AND A.RECV_FLAG = #{st_recv_type} AND A.CLAIM_TYPE = B.CODE AND TO_CHAR(A.CD_DATE,'YYYYMMDD') BETWEEN #{st_fromDate} AND #{st_toDate}
AND (A.SYS_TYPE, A.BUYER) IN
${itm}
ORDER BY A.CD_DATE DESC, A.BUYER, A.VC_NO
